"% Trim solver for nonlinear climb + coordinated-turn
% System: 3 coupled nonlinear equations in alpha, T, delta_e

% --- Given Parameters ---
W = 200000.0;      % lbf
S = 2100.0;        % ft^2
h = 27000.0;       % ft
V = 700.0;         % ft/s
gamma_deg = 4.0;   % deg
phi_deg = 25.0;    % deg

% Lift parameters
CL0 = 0.12;
CLa = 4.9;         % /rad
CLde = 0.4;        % /rad

% Drag parameters
CD0 = 0.023;
k = 0.041;

% Atmosphere
rho0 = 0.0023769;  % slug/ft^3
H_atm = 23800.0;   % ft (scale height)

% Thrust parameters
iT_deg = 2.0;      % deg (thrust line pitch vs body)
zT = 1.8;          % ft (perpendicular arm)

% Pitching moment parameters
Cm0 = 0.018;
Cma = -0.28;       % /rad
Cmde = -0.8;       % /rad
cbar = 16.0;       % ft (mean chord)

% --- Derived Constants (Convert angles to radians) ---
gamma = deg2rad(gamma_deg);
phi = deg2rad(phi_deg);
iT = deg2rad(iT_deg);

% --- Atmosphere & Dynamic Pressure ---
rho = rho0 * exp(-h / H_atm);
q = 0.5 * rho * V^2;

% --- Residuals Function ---
% x = [alpha (rad), T (lbf), delta_e (rad)]
function F = residuals(x, params)
    % Unpack parameters
    W = params.W; S = params.S; gamma = params.gamma; phi = params.phi;
    q = params.q; iT = params.iT; zT = params.zT; cbar = params.cbar;
    CL0 = params.CL0; CLa = params.CLa; CLde = params.CLde;
    CD0 = params.CD0; k = params.k;
    Cm0 = params.Cm0; Cma = params.Cma; Cmde = params.Cmde;

    % Unpack state
    alpha = x(1);
    T = x(2);
    de = x(3);

    % Coefficients
    CL = CL0 + CLa * alpha + CLde * de;
    CD = CD0 + k * CL^2;
    Cm = Cm0 + Cma * alpha + Cmde * de;

    % Forces and Moments
    Lift = q * S * CL;
    Drag = q * S * CD;
    M_aero = q * S * cbar * Cm;
    M_thrust = T * sin(iT) * zT;

    % Equations of Equilibrium
    % 1. Vertical Force Balance
    Eq1 = Lift * cos(phi) + T * sin(alpha + iT) - W * cos(gamma);

    % 2. Along Flight Path Force Balance
    Eq2 = T * cos(alpha + iT) - Drag - W * sin(gamma);

    % 3. Pitching Moment Balance
    Eq3 = M_aero + M_thrust;

    F = [Eq1; Eq2; Eq3];
end

% --- Solver Setup (Newton-Raphson) ---
% Pack parameters struct
p = struct(...
    'W', W, 'S', S, 'gamma', gamma, 'phi', phi, ...
    'q', q, 'iT', iT, 'zT', zT, 'cbar', cbar, ...
    'CL0', CL0, 'CLa', CLa, 'CLde', CLde, ...
    'CD0', CD0, 'k', k, ...
    'Cm0', Cm0, 'Cma', Cma, 'Cmde', Cmde);

% Initial Guess
% alpha ~ 5 deg, T ~ 30000 lbf, de ~ 0 deg
x = [deg2rad(5.0); 30000.0; 0.0];

% Newton Iteration
tol = 1e-10;
max_iter = 50;
dx = 1e-6; % Finite difference step

for iter = 1:max_iter
    F = residuals(x, p);
    if norm(F) < tol
        break;
    end

    % Numerical Jacobian
    J = zeros(3, 3);
    for i = 1:3
        x_pert = x;
        x_pert(i) = x(i) + dx;
        F_pert = residuals(x_pert, p);
        J(:, i) = (F_pert - F) / dx;
    end

    % Update step
    delta = J \ (-F);
    x = x + delta;

    % Simple damping if step is too large (safety for robustness)
    if norm(delta) > 0.1
        x = x - 0.5 * delta; 
    end
end

% --- Output Formatting ---
alpha_rad = x(1);
thrust_lbf = x(2);
de_rad = x(3);

% Load Factor Calculation
n = cos(gamma) / cos(phi);

% Prepare Result Struct
result.alpha_trim_deg = rad2deg(alpha_rad);
result.thrust_lbf = thrust_lbf;
result.delta_e_trim_deg = rad2deg(de_rad);
result.load_factor = n;

% Write JSON
jsonStr = jsonencode(result);
fid = fopen('result.json', 'w');
fwrite(fid, jsonStr);
fclose(fid);"
